const KONTUR = '#1d1b1a';
const ton = (K, f) => (f > 0 ? hell(K.c, f) : f < 0 ? dunkel(K.c, -f) : K.c);

export function b08Zeichner(S, t, p) {
  const D = B08_DATEN[p.b08];
  if (!D) return;
  if (!S.tex && p.muster && p.muster !== 'uni' && istMuster(p.muster)) S.tex = musterFuellung(S, p.muster);
  // Musterflächen aus dem Bild nur, solange das Musterfeld (Q37) nichts gewählt hat (gewählt: produkt.js setzt dessin = '')
  const bildmuster = p.dessin !== '';
  const K = [S];
  const n = 1 + Math.max(0, ...D.regionen.filter((r) => 'tmr'.includes(r[0])).map((r) => r[1]));
  for (let i = 1; i < n; i++) K.push(materialDefs(p.farben?.[i - 1] ?? 'grau', p.materialien?.[i - 1] ?? 'baumwolle', S.defs));
  if (p.glatt) K.forEach((k, i) => { if (i > 0 || !p.muster || p.muster === 'uni') if (k.m === 'strick' || k.m === 'kaschmir' || k.m === 'merino') k.tex = null; });
  let rip = null;
  if (D.regionen.some((r) => r[0] === 'r')) { rip = S.id + 'rp'; S.defs.push(`<pattern id="${rip}" width="1.15" height="4" patternUnits="userSpaceOnUse"><rect width="0.45" height="4" fill="#000" opacity="0.28"/><rect x="0.5" width="0.25" height="4" fill="#fff" opacity="0.08"/></pattern>`); }
  const clip = S.id + 'b08';
  S.defs.push(`<clipPath id="${clip}"><path d="${D.kontur}" fill-rule="evenodd"/></clipPath>`);
  t.push(`<ellipse cx="50" cy="${D.boden + 1.8}" rx="${Math.min(32, D.breite * 0.45).toFixed(1)}" ry="2.4" fill="#000" opacity="0.08"/>`);
  t.push(`<g clip-path="url(#${clip})">`);
  for (const r of D.regionen) {
    const d = r[r.length - 1];
    if (r[0] === 'k') t.push(`<path d="${d}" fill="${KONTUR}"/>`);
    else if (r[0] === 'f') t.push(`<path d="${d}" fill="${r[1]}"/>`);
    else if (r[0] === 'm') { if (bildmuster) t.push(`<path d="${d}" fill="${ton(K[r[1]], r[2])}"/>`); }
    else if (r[0] === 'r') { const k = K[r[1]]; t.push(`<path d="${d}" fill="${ton(k, r[2])}"/>`); if (k.tex) t.push(`<path d="${d}" fill="${k.tex}"/>`); t.push(`<path d="${d}" fill="url(#${rip})"/>`); }
    else { const k = K[r[1]]; t.push(`<path d="${d}" fill="${ton(k, r[2])}"/>`); if (k.tex) t.push(`<path d="${d}" fill="${k.tex}"/>`); }
  }
  // Pailletten: Schuppenraster aus kleinen Plättchen mit Glanzpunkt über dem ganzen Teil
  if (p.pailletten) { const pid = S.id + 'pl'; S.defs.push(`<pattern id="${pid}" width="2.4" height="2.1" patternUnits="userSpaceOnUse"><circle cx="1.2" cy="1.05" r="0.95" fill="#000" opacity="0.12"/><circle cx="0.95" cy="0.8" r="0.38" fill="#fff" opacity="0.45"/><circle cx="0" cy="0" r="0.95" fill="#000" opacity="0.08"/><circle cx="2.4" cy="2.1" r="0.95" fill="#000" opacity="0.08"/></pattern>`); t.push(`<path d="${D.kontur}" fill="url(#${pid})" fill-rule="evenodd"/>`); }
  t.push(`<path d="${D.kontur}" fill="url(#${S.id}l)" fill-rule="evenodd"/>`);
  t.push('</g>');
  // Umriss nachziehen, wo die Kontur im Bild mit dunklen Musterflächen verschmilzt (z. B. Rautenstrick)
  if (p.umriss) t.push(`<path d="${D.kontur}" fill="none" stroke="${KONTUR}" stroke-width="0.7" stroke-linejoin="round"/>`);
}
